properties.property:
local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Spawn = require "actions/Spawn"
local Do = require "actions/Do"
local Wait = require "actions/Wait"
local Animate = require "actions/Animate"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        self.scene:run(Spawn(BlockPlayer{
                            Do(function()
                                self.scene.player.noIdle = true
                            end),
                            Animate(self.scene.player.sprite, "junk_reveal"),
                            Do(function()
                                self.scene.player.sprite:setAnimation("junk_idle")
                            end),
                            Wait(1.5),
                            Animate(self.scene.player.sprite, "junk_shock"),
                            Wait(0.5),
                            self.scene:enterBattle {
                                opponents = {"messbot", "ladybug"},
                                initiative = "opponent"
                            },
                            Do(function()
                                self.scene.player.noIdle = false
                                self:permanentRemove()
                            end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local Spawn = require "actions/Spawn"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        local item = require(self.object.properties.item:sub(4, -5))
                        GameState:grantItem(item, 1)
                        self.scene:run(Spawn(BlockPlayer{
                            MessageBox{message="Found a {h "..(item.name).."}!", sfx="levelup"},
                            Do(function() self:permanentRemove() end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

